```go
package main

import (
    "errors"
    "fmt"
)

func parseAge(age int) error {
    if age < 0 {
        return errors.New("age must not be negative")
    }
    return nil
}

func label(mode int) string {
    switch mode {
    case 1:
        return "ready"
    default:
        panic("unreachable mode")
    }
}

func main() {
    fmt.Println(parseAge(-1))
    fmt.Println(label(1))
}
```
Invalid external data becomes a returned error; the valid internal mode prints `ready` without triggering the invariant panic.

```go
package main

import "fmt"

func safeDivide(a, b int) (result int, err error) {
    defer func() {
        if value := recover(); value != nil {
            result = 0
            err = fmt.Errorf("divide failed: %v", value)
        }
    }()
    if b == 0 {
        panic("zero divisor")
    }
    return a / b, nil
}

func main() {
    value, err := safeDivide(8, 0)
    fmt.Println(value, err)
}
```
The deferred function recovers in the same goroutine, and the caller receives `0` plus a descriptive error.

```go
package main

import "fmt"

func runJob(name string, job func()) (err error) {
    defer func() {
        if value := recover(); value != nil {
            err = fmt.Errorf("job %s panicked: %v", name, value)
        }
    }()
    job()
    return nil
}

func main() {
    err := runJob("import", func() { panic("bad row") })
    fmt.Println(err)
    fmt.Println(runJob("cleanup", func() {}))
}
```
The first job returns a recorded failure, while the second independent job still completes with `<nil>`.
